"""The qbXML 16.0 schema in compact form, generated by scripts/gen-schema.py.
A ref is either a value code (one letter: s text, b true/false, d date, t date-time, a amount, p price,
q quantity, r percent, i whole number, f number) or the id of a model with ordered children."""
from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path
from typing import Any


class Model:
    __slots__ = ("o", "c", "l")

    def __init__(self, o: list[str], c: dict[str, list[Any]], l: dict[str, int]):
        self.o = o  # child element names, in schema order
        self.c = c  # child name -> [ref, repeats (0/1)]
        self.l = l  # text child name -> the most characters QuickBooks takes


@lru_cache(maxsize=None)
def _data() -> dict[str, Any]:
    data = json.loads((Path(__file__).with_name("schema.json")).read_text(encoding="utf-8"))
    data["models"] = {k: Model(v["o"], v["c"], v.get("l", {})) for k, v in data["models"].items()}
    data["iterators"] = set(data["iterators"])
    data["counts"] = set(data["counts"])
    return data


def enums() -> dict[str, list[str]]:
    return _data()["enums"]


def is_model(ref: str) -> bool:
    return len(ref) > 1


def model(ref: str) -> Model | None:
    return _data()["models"].get(ref)


def message_model(message: str) -> Model | None:
    """The content model of a message such as "InvoiceQueryRq" or "InvoiceQueryRs"."""
    ref = _data()["roots"].get(message)
    return _data()["models"].get(ref) if ref else None


def supports_iterator(message: str) -> bool:
    """True when the query can be paged with iterator="Start" / "Continue"."""
    return message in _data()["iterators"]


def supports_count(message: str) -> bool:
    """True when the query can return just a count, with metaData="MetaDataOnly"."""
    return message in _data()["counts"]


def has_message(message: str) -> bool:
    return message in _data()["roots"]


def messages() -> list[str]:
    return list(_data()["roots"])
